    var label = String(storeLabel || "").trim();
    try {
      sessionStorage.setItem(STORE_KEY, id);
      var meta = readScopeMeta() || {};
      meta.storeId = id;
      meta.storeLabel = label;
      meta.storeLabelEn = label;
      localStorage.setItem(META_KEY, JSON.stringify(meta));
    } catch (_) {
      /* ignore */
    }
