    function resolveTagClass(emp) {
      if ((emp.tipType || '') === 'deduct' && (emp.role || '') === 'Cashier') return 'tag-orange';
      return (emp.tipType || '') === 'deduct' ? 'tag-blue' : 'tag-green';
    }

    function canonicalEmployeeStore(value) {
      var store = String(value || '').trim();
      var aliases = {
        'golden dragon chinese kitchen - dallas, tx 75231': '上海陆家嘴店',
        'sakura sushi & ramen house - dallas, tx 75247': '广州天河店',
        '张记火锅': '上海陆家嘴店'
      };
      return aliases[store.toLowerCase()] || store;
    }

    function dedupeEmployees(list) {
      var seenIds = Object.create(null);
      var seenProfiles = Object.create(null);
      return list.filter(function(employee) {
        var id = String(employee.employeeId || '').trim();
        var profileKey = [canonicalEmployeeStore(employee.store).toLowerCase(), String(employee.name || '').trim().toLowerCase(), String(employee.role || '').trim().toLowerCase()].join('|');
        if ((id && seenIds[id]) || (!id && seenProfiles[profileKey])) return false;
        if (id) seenIds[id] = true;
        seenProfiles[profileKey] = true;
        return true;
      });
    }

    function buildEmployeesFromRoster() {
      try {
        var raw = localStorage.getItem(EMPLOYEE_ROSTER_KEY);
        if (!raw) return DEFAULT_EMPLOYEES.slice();
        var list = JSON.parse(raw);
        if (!Array.isArray(list) || list.length === 0) return DEFAULT_EMPLOYEES.slice();
        var normalized = list
          .filter(function(e) { return e && e.active !== false && ['inactive','disabled'].indexOf(String(e.status || '').toLowerCase()) < 0 && String(e.id || '').trim() && String(e.name || '').trim(); })
          .map(function(e) {
            var role = String(e.role || '').trim();
            var tipType = String(e.tipType || 'deduct').trim();
            var baseTip = Number(e.baseTip) || 0;
            var tipRate = Number(e.tipRate);
            tipRate = Number.isFinite(tipRate) ? (tipRate > 1 ? tipRate / 100 : tipRate) : 0;
            return {
              employeeId: 'roster:' + String(e.id).trim(),
              name: String(e.name || '').trim(),
              store: canonicalEmployeeStore(e.store),
              role: role || 'Server',
              tipType: tipType === 'receive' ? 'receive' : 'deduct',
              baseTip: baseTip,
              tipRate: tipRate,
              tagClass: resolveTagClass({ role: role, tipType: tipType })
            };
          });
        return normalized.length ? dedupeEmployees(normalized) : DEFAULT_EMPLOYEES.slice();
      } catch (e) {
        return DEFAULT_EMPLOYEES.slice();
      }
    }

    const employees = buildEmployeesFromRoster();
    var activeSummaryView = 'date';
    var employeeAggregateById = Object.create(null);
    var allEmployeeSummaryAggregates = [];
    var visibleEmployeeSummaryAggregates = [];
    var visibleDailySummaryRows = [];
    var dateSummaryFilters = { allocationStatus: '', businessStatus: '', payoutStatus: '' };
    var employeeSummaryFilters = { role: '', employeeScope: { mode: 'all', ids: [] }, statuses: [] };
    var employeeSummarySort = { key: 'finalAmount', direction: 'desc' };

    function getSelectedRoles() {
      var el = document.getElementById('roleFilter');
      if (!el) return [];
      var cbs = el.querySelectorAll('input[type="checkbox"]:checked');
      return Array.prototype.map.call(cbs, function(c) { return c.value; }).filter(function(v) { return v !== '__all__'; });
    }

    function getSelectedEmployees() {
      var el = document.getElementById('employeeFilter');
      if (!el) return [];
      var cbs = el.querySelectorAll('input[type="checkbox"]:checked');
      return Array.prototype.map.call(cbs, function(c) { return c.value; }).filter(function(v) { return v !== '__all__'; });
    }

    function getSelectedValues(filterId) {
      var el = document.getElementById(filterId);
      if (!el) return [];
      var cbs = el.querySelectorAll('input[type="checkbox"]:checked:not([data-select-all])');
      return Array.prototype.map.call(cbs, function(c) { return c.value; });
    }

    function toggleSelectAll(selectId, checked) {
      var container = document.getElementById(selectId);
      if (!container) return;
      var allCbs = container.querySelectorAll('input[type="checkbox"]:not([data-select-all])');
      allCbs.forEach(function(cb) { cb.checked = !!checked; });
      refreshIndexMultiTags(selectId);
      syncSelectAllState(selectId);
      if (selectId === 'roleFilter') updateEmployeeFilter();
      else if (selectId === 'employeeSummaryEmployeeFilter') handleEmployeeSummaryEmployeeChange();
      else renderDailySummaryList();
    }

    function syncSelectAllState(selectId) {
      var container = document.getElementById(selectId);
      if (!container) return;
      var allCb = container.querySelector('input[data-select-all]');
      var itemCbs = container.querySelectorAll('input[type="checkbox"]:not([data-select-all])');
      if (!allCb || !itemCbs.length) return;
      var allChecked = itemCbs.length > 0 && Array.prototype.every.call(itemCbs, function(c) { return c.checked; });
      allCb.checked = allChecked;
    }

    function toggleIndexMultiSelect(id) {
      var el = document.getElementById(id);
      if (!el) return;
      document.querySelectorAll('.filter-bar .multi-select.open').forEach(function(ms) {
        if (ms.id !== id) ms.classList.remove('open');
      });
      el.classList.toggle('open');
    }

    function removeIndexMultiTag(e, btnEl) {
      e.stopPropagation();
      var selectId = btnEl && btnEl.dataset && btnEl.dataset.selectId;
      var value = btnEl && btnEl.dataset && btnEl.dataset.value;
      if (!selectId || value === undefined) return;
      var container = document.getElementById(selectId);
      var inputs = container ? container.querySelectorAll('input[type="checkbox"]') : [];
      for (var i = 0; i < inputs.length; i++) {
        if (inputs[i].value === value) { inputs[i].checked = false; break; }
      }
      refreshIndexMultiTags(selectId);
      if (selectId === 'roleFilter') updateEmployeeFilter();
      else renderDailySummaryList();
    }

    function refreshIndexMultiTags(selectId) {
      var container = document.getElementById(selectId);
      if (!container) return;
      var tagsEl = container.querySelector('.multi-select-tags');
      if (!tagsEl) return;
      var placeholder = (container.dataset && container.dataset.placeholder) || '请选择';
      var cbs = container.querySelectorAll('input[type="checkbox"]:checked:not([data-select-all])');
      tagsEl.innerHTML = '';
      if (cbs.length === 0) {
        tagsEl.innerHTML = '<span class="multi-select-placeholder">' + placeholder + '</span>';
        return;
      }
      cbs.forEach(function(cb) {
        var tag = document.createElement('span');
        tag.className = 'multi-select-tag';
        var label = cb.dataset && cb.dataset.label ? cb.dataset.label : (cb.value || '');
        tag.innerHTML = escapeSummaryHtml(label) + ' <i data-select-id="' + selectId + '" data-value="' + escapeSummaryHtml(cb.value || '') + '" onclick="removeIndexMultiTag(event, this)">×</i>';
        tagsEl.appendChild(tag);
      });
    }

    function updateEmployeeFilter(skipRender) {
      var roles = getSelectedRoles();
      var prevSelected = getSelectedEmployees();
      var dropdown = document.getElementById('employeeFilterDropdown');
      if (!dropdown) return;
      var list = roles.length > 0
        ? employees.filter(function(e) { return roles.indexOf(e.role) >= 0; })
        : employees;
      var allChecked = list.length > 0 && list.every(function(e) { return prevSelected.indexOf(e.name) >= 0; });
      var allHtml = '<label class="multi-select-option multi-select-all" style="border-bottom:1px solid var(--border-light);margin-bottom:4px;padding-bottom:6px"><input type="checkbox" value="__all__" data-select-all' + (allChecked ? ' checked' : '') + '> 全选</label>';
      var itemsHtml = list.map(function(e) {
        var checked = prevSelected.indexOf(e.name) >= 0 ? ' checked' : '';
        return '<label class="multi-select-option"><input type="checkbox" value="' + (e.name || '').replace(/"/g, '&quot;') + '"' + checked + '> ' + (e.name || '') + '</label>';
      }).join('');
      dropdown.innerHTML = allHtml + itemsHtml;
      refreshIndexMultiTags('employeeFilter');
      if (!skipRender) renderDailySummaryList();
    }

    function pad(n) { return n < 10 ? '0' + n : '' + n; }
    function formatDateKey(d) { return d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate()); }
    function formatTabLabel(d) { return pad(d.getMonth() + 1) + '/' + pad(d.getDate()); }
    function money(v) { return (v < 0 ? '-' : '') + '$' + Math.abs(v).toFixed(2).replace(/\\B(?=(\\d{3})+(?!\\d))/g, ','); }
    function moneySign(v) { return (v >= 0 ? '+' : '-') + '$' + Math.abs(v).toFixed(2).replace(/\\B(?=(\\d{3})+(?!\\d))/g, ','); }
    function roundTip(v) { return +(Number(v) || 0).toFixed(2); }
    function calcTipAfter(before, deducted, received) {
      return roundTip(before - deducted + received);
    }

    function seedRandom(seed) {
      let s = seed;
      return function() { s = (s * 16807 + 0) % 2147483647; return (s - 1) / 2147483646; };
    }

    function getAllocationDeductorContext() {
      var storeSel = document.getElementById('storeSelect');
      var store = storeSel ? (storeSel.value || '').trim() : '';
      if (window.ruleData && ruleData.buildDeductorContextForStore) {
        return ruleData.buildDeductorContextForStore(store);
      }
      return { hasDeductors: false, roles: {}, names: {} };
    }

    function getLegacyRulesForCurrentStore() {
      var storeSel = document.getElementById('storeSelect');
      var store = storeSel ? (storeSel.value || '').trim() : '';
      if (!window.ruleData || !ruleData.getRulesForStore) return [];
      return ruleData.getRulesForStore(store).filter(function(r) {
        return (r.allocationMode || 'legacy_pool') === 'legacy_pool';
      });
    }

    function getRulesForCurrentStore() {
      var storeSel = document.getElementById('storeSelect');
      var store = storeSel ? (storeSel.value || '').trim() : '';
      return window.ruleData && ruleData.getRulesForStore ? ruleData.getRulesForStore(store) : [];
    }

    function getPersonalSalesPctRule() {
      var rules = getLegacyRulesForCurrentStore();
      for (var i = 0; i < rules.length; i++) {
        var cfg = rules[i].deductConfig;
        if (cfg && cfg.personalSalesPct && window.TipOutPersonalSalesDeduct &&
            TipOutPersonalSalesDeduct.entryHasScope(cfg.personalSalesPct)) {
          return rules[i];
        }
      }
      return null;
    }

    /** 演示期：由日期+姓名种子生成 Net Sales，隔离于他人销售额 */
    function genPersonalNetSales(emp, dateKey) {
      var seed = dateKey.split('-').reduce(function(a, b) { return a * 31 + parseInt(b, 10); }, 0) +
        emp.name.length * 13 + emp.name.charCodeAt(0) * 17;
      var rng = seedRandom(seed + 991);
      var dayOfWeek = new Date(dateKey + 'T00:00:00').getDay();
      var weekendBoost = (dayOfWeek === 5 || dayOfWeek === 6) ? 1.35 : 1.0;
      return roundTip((700 + rng() * 1600) * weekendBoost);
    }

    var dayPipelineCache = {};
    function invalidateDayPipelineCache() { dayPipelineCache = {}; }

    function ensureDayPipeline(dateKey) {
      if (dayPipelineCache[dateKey]) return dayPipelineCache[dateKey];
      var rule = getPersonalSalesPctRule();
      if (!rule || !window.TipAllocation || !TipAllocation.runLegacyDayPipeline) {
        dayPipelineCache[dateKey] = null;
        return null;
      }
      var dayEmps = employees.map(function(emp) {
        var seed = dateKey.split('-').reduce(function(a, b) { return a * 31 + parseInt(b, 10); }, 0) +
          emp.name.length * 7 + emp.name.charCodeAt(0);
        var rng = seedRandom(seed);
        var dayOfWeek = new Date(dateKey + 'T00:00:00').getDay();
        var weekendBoost = (dayOfWeek === 5 || dayOfWeek === 6) ? 1.35 : 1.0;
        var tipBefore;
        var deductCtx = getAllocationDeductorContext();
        var shouldDeduct = window.ruleData && ruleData.isEmployeeInDeductorContext
          ? ruleData.isEmployeeInDeductorContext(emp, deductCtx)
          : false;
        if (shouldDeduct || (emp.tipType || '') === 'deduct') {
          tipBefore = roundTip(emp.baseTip * (0.8 + rng() * 0.5) * weekendBoost);
        } else {
          var baseBefore = Number(emp.baseTip) > 0
            ? emp.baseTip * (0.8 + rng() * 0.5)
            : (5 + rng() * 12);
          tipBefore = roundTip(baseBefore * weekendBoost);
        }
        var attendance = (window.TipOutAttendance && TipOutAttendance.getDayStatus)
          ? TipOutAttendance.getDayStatus(emp.name, dateKey)
          : { hours: 0, clockStatus: '未打卡' };
        return {
          id: emp.name,
          name: emp.name,
          role: emp.role,
          tipBefore: tipBefore,
          tipRate: emp.tipRate || 0,
          salesAmount: genPersonalNetSales(emp, dateKey),
          hours: rule.clockin === 'noclock' ? 0 : attendance.hours,
          clockedIn: attendance.clockStatus !== '未打卡',
          orderCount: window.TipOutScenarioSource ? window.TipOutScenarioSource.employee(emp.name,dateKey,{storeId:rule.store}).orders.length : 0
        };
      });
      var pipeline = TipAllocation.runLegacyDayPipeline(rule, dayEmps);
      dayPipelineCache[dateKey] = pipeline;
      return pipeline;
    }

    function formatHoursDisplay(hours) {
      var n = Number(hours);
      if (!isFinite(n) || n === 0) return '0';
      return (Math.round(n * 100) / 100).toString();
    }

    function clockStatusTagHtml(clockStatus) {
      var status = clockStatus || '未打卡';
      var tagClass = status === '已打卡' ? 'tag-green' : 'tag-orange';
      return '<span class="tag ' + tagClass + '">' + status + '</span>';
    }

    function attachAttendance(row, emp, dateKey) {
      var att = (window.TipOutAttendance && TipOutAttendance.getDayStatus)
        ? TipOutAttendance.getDayStatus(emp.name, dateKey, { employeeId: emp.employeeId, storeId: (document.getElementById('storeSelect') || {}).value })
        : { hours: 0, clockStatus: '未打卡' };
      row.hours = att.effectiveHours === undefined ? att.hours : att.effectiveHours;
      row.originalPunchHours = att.originalHours === undefined ? att.hours : att.originalHours;
      row.posEffectiveHours = att.effectiveHours === undefined ? att.hours : att.effectiveHours;
      row.punchHours = row.originalPunchHours;
      row.punchHoursValid = att.clockStatus !== '未打卡' && isFinite(Number(att.hours)) && Number(att.hours) >= 0;
      row.clockStatus = att.clockStatus;
      row.punchSessions = Array.isArray(att.punchSessions)
        ? att.punchSessions.map(function(session) { return Object.assign({}, session); })
        : undefined;
      row.manualHourEntries = window.TipOutManualHours
        ? TipOutManualHours.listForEmployee(dateKey, { employeeId: String(emp.employeeId || '').replace(/^roster:/, ''), name: emp.name })
        : [];
      var manualByRule = {};
      row.manualHourEntries.forEach(function(entry) { manualByRule[String(entry.poolId) + '::' + String(entry.ruleId)] = entry; });
      row.allocationHourEntries = getRulesForCurrentStore().map(function(rule, index) {
        var poolId = String(rule.poolId || rule.id || ('pool-' + index));
        var ruleId = String(rule.id || rule.ruleId || ('rule-' + index));
        var manual = manualByRule[poolId + '::' + ruleId] || row.manualHourEntries.find(function(entry) { return String(entry.ruleId) === ruleId; });
        var method = rule.distribution || rule.distributionMethod || rule.method;
        var usesHours = method === 'hours';
        var maxHours = rule.workHoursConfig && rule.workHoursConfig.mode === 'capped' ? rule.workHoursConfig.maxHoursPerDay : null;
        var resolved = TipOutSummaryUi.resolveRuleAllocationHours({
          usesHours: usesHours,
          clockMode: rule.clockin,
          originalPunchHours: row.originalPunchHours,
          posEffectiveHours: row.posEffectiveHours,
          manualHours: manual ? manual.hours : null,
          maxHours: maxHours
        });
        if(rule.allocationScope==='shift'&&usesHours){
          try{var scopeStore=(document.getElementById('storeSelect')||{}).value||'';var result=window.TipOutTimeWindow.allocateRule(rule,window.TipOutScenarioSource.day(dateKey,scopeStore),dateKey);var currentId=String(emp.employeeId||'').replace(/^roster:/,'');var person=result.employeeAmounts.find(function(p){return currentId?String(p.employeeId)===currentId:p.name===emp.name;});resolved={hours:person?person.allocationHours:0,hoursValid:true,source:'shift'};}
          catch(error){resolved={hours:null,hoursValid:false,source:'shift'};}
        }
        return {
          poolId: poolId,
          poolName: rule.poolName || rule.name || '未命名小费池',
          poolKind: rule.poolKind === 'surcharge' ? 'surcharge' : 'tip',
          ruleId: ruleId,
          ruleName: rule.ruleName || rule.name || '未命名规则',
          usesHours: usesHours,
          hours: resolved.hours,
          hoursValid: resolved.hoursValid,
          source: resolved.source,
          dateKey: dateKey
        };
      });
      row.manualHourEntries.forEach(function(entry) {
        var key = String(entry.poolId) + '::' + String(entry.ruleId);
        if (!row.allocationHourEntries.some(function(item) { return item.poolId + '::' + item.ruleId === key; })) {
          row.allocationHourEntries.push(Object.assign({}, entry, { usesHours: true, hoursValid: true, source: 'manual', dateKey: dateKey }));
        }
      });
      var store = (document.getElementById('storeSelect') || {}).value || '';
      var confirmed = window.TipOutAllocationResults && TipOutAllocationResults.read(store, dateKey);
      if (confirmed && Array.isArray(confirmed.pools)) {
        var confirmedRules = confirmed.editorState && Array.isArray(confirmed.editorState.rules)
          ? confirmed.editorState.rules : getRulesForCurrentStore();
        confirmed.pools.forEach(function(pool) {
          var ruleId = String(pool.ruleId || '');
          var rule = confirmedRules.find(function(item) { return String(item.id || '') === ruleId; });
          if (!rule || rule.distribution !== 'hours') return;
          var employee = (pool.employees || []).find(function(item) {
            var currentId = String(emp.employeeId || '').replace(/^roster:/, '');
            return currentId && item.employeeId ? String(item.employeeId) === currentId : item.name === emp.name;
          });
          if (!employee) return;
          var poolId = String(pool.poolId || rule.poolId || rule.id || '');
          var entry = row.allocationHourEntries.find(function(item) { return item.poolId === poolId && item.ruleId === ruleId; });
          if (!entry) {
            entry = { poolId: poolId, poolName: pool.poolName || '未命名小费池', poolKind: pool.poolKind || 'tip',
              ruleId: ruleId, ruleName: pool.ruleName || '未命名规则', usesHours: true, dateKey: dateKey };
            row.allocationHourEntries.push(entry);
          }
          entry.hours = Number(employee.hours);
          entry.hoursValid = isFinite(entry.hours) && entry.hours >= 0;
          if (employee.hoursSource === 'manual') entry.source = 'manual';
          if (employee.hoursSource === 'shift') entry.source = 'shift';
        });
      }
      return row;
    }

    function genDailyTip(emp, dateKey) {
      if (window.TipOutScenarioSource) {
        var scenarioStore = (document.getElementById('storeSelect') || {}).value;
        var savedResult = window.TipOutAllocationResults && TipOutAllocationResults.read(scenarioStore,dateKey);
        var fact = window.TipOutScenarioSource.employee(emp.name, dateKey, { employeeId: emp.employeeId, storeId: scenarioStore });
        var hasContributionDemoRules = getRulesForCurrentStore().some(function(rule) { return !!rule.demoScenarioKey && !!rule.deductConfig; });
        if (!savedResult || Array.isArray(savedResult.scenarioFacts) || hasContributionDemoRules) {
          if (savedResult && Array.isArray(savedResult.scenarioFacts)) fact = savedResult.scenarioFacts.find(function(f) { return f.employeeId === String(emp.employeeId).replace(/^roster:/,''); }) || fact;
          var scenarioRow = attachAttendance({ date: dateKey, before: fact.originalTips, deducted: 0, received: 0, after: fact.originalTips,
            salesAmount: fact.salesAmount, orderCount: fact.orders.length, scenarioId: fact.scenarioId }, emp, dateKey);
          if (savedResult) {
            // Retain the existing employee contribution policy; this adapter changes facts, not rule semantics.
            var contributionContext = getAllocationDeductorContext();
            if (window.ruleData && ruleData.isEmployeeInDeductorContext(emp, contributionContext)) scenarioRow.deducted = roundTip(fact.originalTips * (emp.tipRate || 0));
            if (Array.isArray(savedResult.employeeContributions)) {
              var contribution = savedResult.employeeContributions.find(function(item) { return String(item.employeeId) === String(emp.employeeId).replace(/^roster:/,''); });
              scenarioRow.deducted = contribution ? roundTip(contribution.amount) : 0;
            }
            savedResult.pools.forEach(function(pool) { pool.employees.forEach(function(e) {
              if (String(e.employeeId) === String(emp.employeeId).replace(/^roster:/,'')) scenarioRow.received += Number(e.amount || 0);
            }); });
            var employeeAmounts = Array.isArray(savedResult.employeeAmounts) ? savedResult.employeeAmounts : null;
            if (!employeeAmounts) {
              var demoRules = getRulesForCurrentStore().filter(function(rule) { return !!rule.demoScenarioKey && !!rule.deductConfig; });
              var compatibilityFacts = Array.isArray(savedResult.scenarioFacts) && savedResult.scenarioFacts.some(function(item) { return item && item.version === 'tipout-scenarios-v1'; })
                ? savedResult.scenarioFacts
                : (demoRules.length && window.TipOutScenarioSource ? window.TipOutScenarioSource.day(dateKey,scenarioStore) : null);
              if (demoRules.length && compatibilityFacts) employeeAmounts = window.TipAllocation.collectScenarioEmployeeAmounts(demoRules,compatibilityFacts);
            }
            if (employeeAmounts) {
              var employeeAmount = employeeAmounts.find(function(item) { return String(item.employeeId) === String(emp.employeeId).replace(/^roster:/,''); });
              scenarioRow.deducted = employeeAmount ? roundTip(employeeAmount.deducted) : 0;
              scenarioRow.received = employeeAmount ? roundTip(employeeAmount.received) : 0;
            }
            scenarioRow.received = roundTip(scenarioRow.received);
            scenarioRow.after = calcTipAfter(scenarioRow.before,scenarioRow.deducted,scenarioRow.received);
            scenarioRow.hours = fact.attendance.effectiveHours;
            scenarioRow.originalPunchHours = scenarioRow.punchHours = fact.attendance.originalHours;
            scenarioRow.clockStatus = fact.attendance.clockStatus;
            scenarioRow.punchSessions = fact.attendance.punchSessions;
          }
          return scenarioRow;
        }
      }
      var pipeline = ensureDayPipeline(dateKey);
      if (pipeline && pipeline.byName && pipeline.byName[emp.name]) {
        var row = pipeline.byName[emp.name];
        return attachAttendance({
          date: dateKey,
          before: row.before,
          deducted: row.deducted,
          received: row.received,
          after: row.after,
          due: row.due,
          shortfall: row.shortfall,
          salesAmount: row.salesAmount
        }, emp, dateKey);
      }

      const seed = dateKey.split('-').reduce((a, b) => a * 31 + parseInt(b), 0) + emp.name.length * 7 + emp.name.charCodeAt(0);
      const rng = seedRandom(seed);
      const dayOfWeek = new Date(dateKey + 'T00:00:00').getDay();
      const weekendBoost = (dayOfWeek === 5 || dayOfWeek === 6) ? 1.35 : 1.0;

      var before = 0;
      var deducted = 0;
      var received = 0;

      var deductCtx = getAllocationDeductorContext();
      var shouldDeduct = window.ruleData && ruleData.isEmployeeInDeductorContext
        ? ruleData.isEmployeeInDeductorContext(emp, deductCtx)
        : false;

      if (shouldDeduct) {
        before = roundTip(emp.baseTip * (0.8 + rng() * 0.5) * weekendBoost);
        deducted = roundTip(before * (emp.tipRate || 0));
        if (emp.role === 'Server') {
          received = roundTip((18 + rng() * 32) * weekendBoost);
        }
      } else {
        var baseBefore = Number(emp.baseTip) > 0
          ? emp.baseTip * (0.8 + rng() * 0.5)
          : (5 + rng() * 12);
        before = roundTip(baseBefore * weekendBoost);
        received = roundTip((25 + rng() * 45) * weekendBoost);
        deducted = 0;
      }

      var after = calcTipAfter(before, deducted, received);
      return attachAttendance({ date: dateKey, before: before, deducted: deducted, received: received, after: after }, emp, dateKey);
    }

    function buildDateRange(s, e) {
      if (!s || !e) return [];
      const start = new Date(s + 'T00:00:00');
      const end = new Date(e + 'T00:00:00');
      if (isNaN(start) || isNaN(end) || start > end) return [];
      const dates = [];
      const cur = new Date(start);
      while (cur <= end) {
        dates.push(formatDateKey(cur));
        cur.setDate(cur.getDate() + 1);
      }
      return dates;
    }
    var lastValidSummaryDateRange = null;
    var activeSummaryDatePreset = '';

    function syncSummaryDatePresetUi() {
      var group = document.getElementById('summaryDatePresets');
      if (!group) return;
      var range = activeSummaryDatePreset && TipOutSummaryDateSort.quickDateRange(activeSummaryDatePreset);
      if (!range || range.startDate !== document.getElementById('dateStart').value || range.endDate !== document.getElementById('dateEnd').value) activeSummaryDatePreset = '';
      group.querySelectorAll('[data-date-preset]').forEach(function(button) {
        button.setAttribute('aria-pressed', String(button.dataset.datePreset === activeSummaryDatePreset));
      });
    }

    function applySummaryDatePreset(key) {
      var range = TipOutSummaryDateSort.quickDateRange(key);
      if (!range) return false;
      document.getElementById('dateStart').value = range.startDate;
      document.getElementById('dateEnd').value = range.endDate;
      if (!handleSummaryDateRangeChange()) return false;
      activeSummaryDatePreset = key;
      syncSummaryDatePresetUi();
      return true;
    }

    function validateSummaryDateRange(focusError) {
      var start = document.getElementById('dateStart');
      var end = document.getElementById('dateEnd');
      var feedback = document.getElementById('summaryDateRangeError');
      var s = start.value, e = end.value, message = '', invalid = null;
      if (!s) { message = '请选择开始日期'; invalid = start; }
      else if (!e) { message = '请选择结束日期'; invalid = end; }
      else if (!TipOutSummaryDateSort.isValidDateRange(s, s)) { message = '请输入有效的开始日期'; invalid = start; }
      else if (!TipOutSummaryDateSort.isValidDateRange(e, e)) { message = '请输入有效的结束日期'; invalid = end; }
      else if (s > e) { message = '开始日期不能晚于结束日期'; invalid = start; }
      [start, end].forEach(function(input) {
        if (input === invalid) input.setAttribute('aria-invalid', 'true');
        else input.removeAttribute('aria-invalid');
      });
      if (feedback) {
        feedback.hidden = !message;
        feedback.textContent = message ? message + '。' + (lastValidSummaryDateRange
          ? '当前仍显示上次有效查询结果（' + lastValidSummaryDateRange.startDate.replace(/-/g, '/') + '—' + lastValidSummaryDateRange.endDate.replace(/-/g, '/') + '），修正日期后更新。'
          : '修正日期后查询。') : '';
      }
      if (invalid && focusError) invalid.focus();
      return !invalid;
    }

    function handleSummaryDateRangeChange() {
      activeSummaryDatePreset = '';
      syncSummaryDatePresetUi();
      if (!validateSummaryDateRange(true)) return false;
      invalidateDayPipelineCache();
      renderSummaryViews();
      captureSummaryUiState('', '');
      scheduleSummaryAutoAllocation();
      return true;
    }

    function getDateRange() {
      const s = document.getElementById('dateStart').value;
      const e = document.getElementById('dateEnd').value;
      return buildDateRange(s, e);
    }

