    function applyPoolKindLabelEl(el) {
      if (!el) return;
      var base = el.getAttribute('data-pool-label');
      if (!base) return;
      el.textContent = isSurchargePoolKind() ? tipTerm(base) : base;
    }

    function applyFieldDescWrapLabels() {
      document.querySelectorAll('.field-desc-wrap[data-pool-label]').forEach(function(wrap) {
        var base = wrap.getAttribute('data-pool-label');
        if (!base) return;
        var label = isSurchargePoolKind() ? tipTerm(base) : base;
        var icon = wrap.querySelector('.field-desc-icon');
        var fieldId = wrap.getAttribute('data-field-id') || '';
        if (icon) {
          icon.setAttribute('data-label', label);
          icon.setAttribute('onclick', "event.preventDefault();openFieldDescEditor('" + fieldId + "','" + label.replace(/'/g, "\\\\'") + "')");
        }
        Array.prototype.slice.call(wrap.childNodes).forEach(function(n) {
          if (n.nodeType === 3) wrap.removeChild(n);
        });
        wrap.insertBefore(document.createTextNode(label + ' '), icon || null);
      });
    }

    function applyPoolKindStaticLabels() {
      document.querySelectorAll('[data-pool-label]').forEach(function(el) {
        if (el.classList && el.classList.contains('field-desc-wrap')) return;
        applyPoolKindLabelEl(el);
      });
      applyFieldDescWrapLabels();
      var deductTipItem = document.querySelector('#deductAddOptionMenu .add-option-menu-item[data-basis="tip_income"]');
      if (deductTipItem) {
        var deductBase = deductTipItem.getAttribute('data-pool-label') || '按照小费收入占比';
        deductTipItem.textContent = isSurchargePoolKind() ? tipTerm(deductBase) : deductBase;
      }
    }

    function getPoolRuleBaseNames() {
      var base = {
        sales: '销售额',
        personal_sales: '按个人销售额',
        tips: '小费',
        surcharge: '加收服务费',
        manual: '手动上报小费',
        custom: isSurchargePoolKind() ? '自定义加收' : '自定义小费'
      };
      if (!isSurchargePoolKind()) return base;
      var out = {};
      Object.keys(base).forEach(function(k) { out[k] = tipTerm(base[k]); });
      return out;
    }

    function getAllowedPoolRuleTypes() {
      return isSurchargePoolKind()
        ? ['surcharge', 'custom']
        : ['sales', 'personal_sales', 'tips', 'manual', 'custom'];
    }

    /** 解析池规则类型：兼容 personal_sales_1 这类含下划线的 type */
    function parsePoolRuleType(ruleId, fallbackType) {
      if (fallbackType) return fallbackType;
      var id = String(ruleId || '');
      if (id === 'personal_sales' || id.indexOf('personal_sales_') === 0) return 'personal_sales';
      return id.split('_')[0];
    }

    function isSalesLikePoolType(type) {
      return type === 'sales' || type === 'personal_sales';
    }

    /** 当前销售额抽屉是否处于「角色必选」上下文（扣除方 / 池·按个人销售额） */
    function isSalesRoleRequiredContext() {
      if (editingDeductValueBasis) return true;
      if (!currentEditingRuleId || editingPersonalSalesPctConditions) return false;
      var card = document.getElementById('rule-' + currentEditingRuleId);
      var type = (card && card.dataset.ruleType) || parsePoolRuleType(currentEditingRuleId);
      return type === 'personal_sales';
    }

    function getPoolRuleTypeById(ruleId) {
      var card = document.getElementById('rule-' + ruleId);
      return (card && card.dataset.ruleType) || parsePoolRuleType(ruleId);
    }

    function isMultiInstancePoolType(type) {
      return type === 'sales' || type === 'personal_sales' || type === 'tips' || type === 'surcharge';
    }

    function getPoolKindPageTitle(isEdit) {
      if (isSurchargePoolKind()) {
        return isEdit ? '编辑加收服务费池分配规则' : '新增加收服务费池分配规则';
      }
      return isEdit ? '编辑小费分配规则' : '新增小费分配规则';
    }

    function applyPoolKindUi(isEdit) {
      var pt = document.getElementById('pageTitle');
      if (pt) pt.textContent = getPoolKindPageTitle(!!isEdit);
      document.title = getPoolKindPageTitle(!!isEdit) + ' - TipOut';
      applyPoolKindStaticLabels();
      var customItem = document.querySelector('#addOptionMenu .add-option-menu-item[data-type="custom"]');
      if (customItem) customItem.textContent = getPoolRuleBaseNames().custom;
      var allowed = getAllowedPoolRuleTypes();
      document.querySelectorAll('#addOptionMenu .add-option-menu-item').forEach(function(item) {
        var type = item.dataset.type;
        item.style.display = allowed.indexOf(type) >= 0 ? '' : 'none';
        if (item.getAttribute('data-pool-label')) applyPoolKindLabelEl(item);
      });
      updateAddMenu();
      updateSurchargeConditionMenu();
      updateDeductRulesVisibility();
      syncRuleEditorContext();
    }

    function initPoolKindFromParams(params, isEdit) {
      if (params && params.poolKind === 'surcharge') currentPoolKind = 'surcharge';
      else currentPoolKind = 'tip';
      applyPoolKindUi(isEdit);
    }

    var FIELD_DESC_STORAGE_KEY = 'ruleAddFieldDesc';
    function getFieldDesc(fieldId) {
      try {
        var raw = localStorage.getItem(FIELD_DESC_STORAGE_KEY);
        if (!raw) return '';
        var obj = JSON.parse(raw);
        return (obj && obj[fieldId]) ? String(obj[fieldId]) : '';
      } catch (e) { return ''; }
    }
    function setFieldDesc(fieldId, text) {
      try {
        var raw = localStorage.getItem(FIELD_DESC_STORAGE_KEY);
        var obj = raw ? JSON.parse(raw) : {};
        obj[fieldId] = text ? String(text).trim() : '';
        if (!obj[fieldId]) delete obj[fieldId];
        localStorage.setItem(FIELD_DESC_STORAGE_KEY, JSON.stringify(obj));
      } catch (e) {}
    }
    var fieldDescEditingId = null;
    function openFieldDescEditor(fieldId, labelText) {
      fieldDescEditingId = fieldId;
      document.getElementById('fieldDescModalLabel').textContent = '字段：' + (labelText || fieldId);
      document.getElementById('fieldDescModalText').value = getFieldDesc(fieldId);
      if (typeof openModal === 'function') openModal('fieldDescModal');
    }
    function saveFieldDesc() {
      if (!fieldDescEditingId) return;
      var text = document.getElementById('fieldDescModalText').value.trim();
      setFieldDesc(fieldDescEditingId, text);
      var icon = document.querySelector('.field-desc-icon[data-field-id="' + fieldDescEditingId + '"]');
      if (icon) icon.classList.toggle('has-desc', !!text);
      fieldDescEditingId = null;
      if (typeof closeModal === 'function') closeModal('fieldDescModal');
      showNotification('说明已保存');
    }
    var fieldDescTooltipEl = null;
    var fieldDescTooltipTimer = null;
    function showFieldDescTooltip(e, fieldId) {
      var text = getFieldDesc(fieldId);
      if (!text) return;
      fieldDescTooltipEl = document.getElementById('fieldDescTooltip');
      if (!fieldDescTooltipEl) return;
      fieldDescTooltipEl.textContent = text;
      fieldDescTooltipEl.classList.add('show');
      fieldDescTooltipEl.dataset.forField = fieldId;
      var x = e.clientX, y = e.clientY;
      fieldDescTooltipEl.style.left = (x + 12) + 'px';
      fieldDescTooltipEl.style.top = (y + 8) + 'px';
    }
    function initFieldDescTooltip() {
      document.querySelectorAll('.field-desc-icon').forEach(function(icon) {
        if (getFieldDesc(icon.dataset.fieldId)) icon.classList.add('has-desc');
      });
      document.addEventListener('mouseover', function(e) {
        var icon = e.target.closest('.field-desc-icon');
        var wrap = e.target.closest('.field-desc-wrap');
        if (icon && icon.dataset.fieldId) showFieldDescTooltip(e, icon.dataset.fieldId);
        else if (wrap && wrap.dataset.fieldId) showFieldDescTooltip(e, wrap.dataset.fieldId);
      });
      document.addEventListener('mouseout', function(e) {
        var related = e.relatedTarget;
        if (related && (related.closest('.field-desc-wrap') || related.closest('#fieldDescTooltip'))) return;
        hideFieldDescTooltip();
      });
    }
    function hideFieldDescTooltip() {
      var el = document.getElementById('fieldDescTooltip');
      if (el) el.classList.remove('show');
    }

