    function updateAddMenu() {
      var allowed = getAllowedPoolRuleTypes();
      var hasSales = hasPoolRuleType('sales');
      var hasPersonalSales = hasPoolRuleType('personal_sales');
      document.querySelectorAll('#addOptionMenu .add-option-menu-item').forEach(item => {
        const type = item.dataset.type;
        if (allowed.indexOf(type) < 0) {
          item.style.display = 'none';
          return;
        }
        item.style.display = '';
        var disabled = false;
        if (type === 'sales' && hasPersonalSales) disabled = true;
        else if (type === 'personal_sales' && hasSales) disabled = true;
        else if (type === 'tips' || type === 'surcharge') disabled = false;
        else if (type !== 'sales' && type !== 'personal_sales' && existingRules[type]) disabled = true;
        item.classList.toggle('disabled', disabled);
      });
      var customItem = document.querySelector('#addOptionMenu .add-option-menu-item[data-type="custom"]');
      if (customItem) customItem.textContent = getPoolRuleBaseNames().custom;
    }

